#include <stdio.h>

int main(void)
{
    int n = 5070;
    int sum = 0;
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    printf("%d\n", sum);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n = 120;
    int r = 0;
    while (n > 0) {
        r = r * 10 + n % 10;
        n /= 10;
    }
    printf("%d\n", r);
    return 0;
}

